import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { taintCanaryTest } from "./rules/taint.js";
const MUTATING = /^(POST|PUT|PATCH|DELETE)$/i;
export function buildAuthzMatrix(inv) {
    const rows = [];
    for (const r of inv.routes) {
        const guard = r.guard || null;
        rows.push({
            path: r.path,
            method: (r.method ?? "GET").toUpperCase(),
            kind: r.kind,
            guard,
            exposure: guard ? "guarded" : "unguarded",
            authz_risk: MUTATING.test(r.method ?? "") && !guard,
        });
    }
    return rows;
}
/** writes the quarantine folder; returns the created file paths */
export function writeQuarantine(dir, input) {
    mkdirSync(dir, { recursive: true });
    const written = [];
    const riskRows = input.matrix.filter((r) => r.authz_risk);
    const base = input.baseUrl || "process.env.STAGING_URL || 'http://localhost:3000'";
    // ---- authz-matrix.json ----
    const jsonPath = join(dir, "authz-matrix.json");
    writeFileSync(jsonPath, JSON.stringify({ source: input.source, generated_by: "anubis-guardian (quarantine — the tool never executes these)", rows: input.matrix }, null, 2));
    written.push(jsonPath);
    // ---- authz-matrix.md ----
    const lines = [
        "# Authorization Matrix — quarantine output",
        "",
        `Source: ${input.source}`,
        "",
        "Generated by `anubis-guardian test-authz`. The TOOL does not run anything here —",
        "you review the matrix and run the generated tests yourself against staging.",
        "",
        "| Endpoint | Method | Kind | Guard | Exposure | Authz risk |",
        "|---|---|---|---|---|---|",
        ...input.matrix.map((r) => `| \`${r.path}\` | ${r.method} | ${r.kind} | ${r.guard ?? "—"} | ${r.exposure} | ${r.authz_risk ? "⚠️ verify" : "—"} |`),
        "",
        riskRows.length
            ? `⚠️ ${riskRows.length} mutating endpoint(s) have no guard signal — the generated Supertest suite asserts 401/403 for unauthenticated calls and will FAIL until they are protected (or explicitly documented as public).`
            : "No unguarded mutating endpoints found by static analysis.",
        "",
    ];
    const mdPath = join(dir, "authz-matrix.md");
    writeFileSync(mdPath, lines.join("\n"));
    written.push(mdPath);
    // ---- generated Supertest suite (failing until fixed — owner runs it) ----
    if (riskRows.length) {
        const testLines = [
            `/**`,
            ` * Generated by Anubis Guardian test-authz (quarantine) — the tool does NOT run this file.`,
            ` * Purpose: differential authz assertion — every unauthenticated mutating call must be`,
            ` * rejected (401/403/redirect). These tests FAIL on the vulnerable build and PASS after the fix.`,
            ` * Setup: npm i -D supertest jest @types/jest && BASE_URL points at staging.`,
            ` */`,
            `const request = require('supertest');`,
            `const BASE = ${base};`,
            ``,
            ...riskRows.flatMap((r) => [
                `describe('authz: ${r.method} ${r.path.replace(/'/g, "\\'")}', () => {`,
                `  it('rejects unauthenticated calls (401/403/redirect)', async () => {`,
                `    const res = await request(BASE)`,
                `      .${r.method.toLowerCase()}('${r.path.replace(/'/g, "\\'")}')${r.method === "GET" ? "" : `.send({ __canary__: 'anubis-guardian' })`};`,
                `    expect([401, 403, 302, 307]).toContain(res.status);`,
                `  });`,
                `});`,
                ``,
            ]),
        ];
        const testPath = join(dir, "authz.supertest.test.js");
        writeFileSync(testPath, testLines.join("\n"));
        written.push(testPath);
    }
    // ---- taint canaries ----
    for (const f of input.taintFindings) {
        const safeName = `${f.id}-${f.file}`.replace(/[^A-Za-z0-9._-]+/g, "_");
        const p = join(dir, `taint-${safeName}.playwright.test.js`);
        writeFileSync(p, taintCanaryTest({ id: f.id, file: f.file, line: f.line, evidence: { masked: f.evidence.masked } }));
        written.push(p);
    }
    // ---- README (the honesty note) ----
    const readme = [
        "# anubis-quarantine",
        "",
        "Generated tests + matrices from Anubis Guardian. **The tool never executes these**",
        "(execution-safety contract, plan §9.7). Review them, adapt BASE URLs to staging, and run:",
        "",
        "```bash",
        "npx jest authz.supertest.test.js        # authz gaps: expect 401/403 while open",
        "npx playwright test taint-*.test.js     # taint canaries: must fail while vulnerable",
        "```",
        "",
        "Delete this folder after triage, or keep it as the fix checklist. It is NOT wired into CI by design.",
        "",
    ].join("\n");
    const readmePath = join(dir, "README.md");
    writeFileSync(readmePath, readme);
    written.push(readmePath);
    return written;
}
